// searchErrorCause is the loggable text of a search error. A *url.Error holds
// the full request URL, which carries the text the user typed, so only its Op
// and Err are kept.
func searchErrorCause(err error) string {
	var ue *url.Error
	if errors.As(err, &ue) {
